sp_widget.client_script:
function($scope, $rootScope, $window, $location, $uibModal, spUtil, $http, $sce, spAriaUtil, $timeout) {
    var c = this;
	var isOpenedInDesigner = location.pathname == "/$spd.do"; //this checks if the page is opened in designer or not
	if(c.data.isloggedIn && !isOpenedInDesigner){
		var url = "/" + c.data.portal_url_suffix + "?id=" + c.data.landing_page;
    $location.url(url);
	}

    if (c.data.has_extrnl_plugin) {
        $scope.emailPattern = /^([\w-]+(?:\.[\w-]+)*)@((?:[\w-]+\.)*\w[\w-]{0,66})\.([a-z]{2,6}(?:\.[a-z]{2})?)$/i;
        $scope.phoneNumbr = /^\s*(?:\+?(\d{1,3}))?[-. (]*(\d{3})[-. )]*(\d{3})[-. ]*(\d{4})(?: *x(\d+))?\s*$/;
		c.fieldSuccessMsgs = c.data.fieldSuccessMsgs;
		c.fieldErrorMsgs = c.data.fieldErrorMsgs;
		c.requiredLabel = c.data.requiredLabel;
		c.requiredFilledLabel = c.data.requiredFilledLabel;
		c.labelMap = c.data.labelMap;
		$scope.namePattern = /^[a-z ,.'-]+$/i;
        $scope.inputType = 'password';
				c.data.emailInvalid = false;
				c.data.emailError = false; 
        c.policy = false;
        c.captchaVerified = false;
				var oldEmail = ''; 
        $scope.$on('captchaVerified', function(event, obj) {
            c.captchaVerified = obj.captchaVerified;
            c.grc = obj.grc;
            scope.$apply();
        });

		$scope.getLiveErrorMessage = function(key) {
			return c.fieldErrorMsgs[key];
		};

		$scope.getLiveSuccessMessage = function(key) {
			return c.fieldSuccessMsgs[key];
		};

        jQuery(document).on('click', '.resend-link', function() {
            c.data.resend_link = true;
            c.data.email = c.email;
            c.server.get({
                'email': c.data.email,
                'resend_link': c.data.resend_link
            }).then(
                function(response) {
                    window.location.href = "/" + c.data.portal_url_suffix + "?id=" + c.data.landing_page + "&register_response=" + response.data.message;
                });
        });
        $(document).on('click', '.comm-login', function() {
             $location.url("/" + c.data.portal_url_suffix + "?id=" + c.data.portal_login);
        });

		var sendAriaLiveMessage = function(message) {
			$timeout(function(){
				spAriaUtil.sendLiveMessage(message);
			},500)
		};

		//Sending aria live message based on field's status when a field is focused
		c.sendFieldStatusMessage = function(userForm, event){
			var fieldName = event.target.attributes.name.value + '';
			if(fieldName == "email") {
				if((userForm[fieldName].$dirty && userForm[fieldName].$error.required) || userForm[fieldName].$error.pattern)
					sendAriaLiveMessage(c.labelMap[fieldName] + "," + c.fieldErrorMsgs["email_invalid_format"]);
				else if(userForm[fieldName].$dirty && userForm[fieldName].$error.maxlength)
					sendAriaLiveMessage(c.labelMap[fieldName] + "," + c.fieldErrorMsgs["email_invalid_size"]);
				else if(userForm[fieldName].$dirty && !userForm[fieldName].$error.required && !userForm[fieldName].$error.pattern && !userForm[fieldName].$error.maxlength)
					sendAriaLiveMessage(c.labelMap[fieldName] + "," + c.fieldSuccessMsgs[fieldName]);
			}
			else if(fieldName == "first_name" || fieldName == "last_name") {
				if((userForm[fieldName].$dirty && userForm[fieldName].$error.required) || userForm[fieldName].$error.pattern)
					sendAriaLiveMessage(c.labelMap[fieldName] + "," + c.fieldErrorMsgs[fieldName]);
				else if(userForm[fieldName].$dirty && !userForm[fieldName].$error.required && !userForm[fieldName].$error.pattern)
					sendAriaLiveMessage(c.labelMap[fieldName] + "," + c.fieldSuccessMsgs[fieldName]);
			}
			else if(fieldName == "phone_number") {
				if(userForm[fieldName].$dirty && userForm[fieldName].$error.pattern)
					sendAriaLiveMessage(c.labelMap[fieldName] + "," + c.fieldErrorMsgs[fieldName]);
				else if(userForm[fieldName].$dirty && !userForm[fieldName].$error.pattern && c.phone_number.length > 0)
					sendAriaLiveMessage(c.labelMap[fieldName] + "," + c.fieldSuccessMsgs[fieldName])
			}
			else if(fieldName == "password" || fieldName == "confirm_password") {
				if(userForm[fieldName].$dirty && userForm[fieldName].$invalid)
					sendAriaLiveMessage(c.labelMap[fieldName] + "," + c.fieldErrorMsgs[fieldName]);
				else if(userForm[fieldName].$dirty && !userForm[fieldName].$invalid)
					sendAriaLiveMessage(c.labelMap[fieldName]+ "," + c.fieldSuccessMsgs[fieldName]);
			}
		};
        c.triggerEmailCheck = function(userForm) {
            c.data.email = userForm.email.$viewValue;
						c.data.emailError = false;
            if (c.data.email && $scope.emailPattern.test(c.data.email)) {
                c.data.validate_email = true;
                if (c.data.whitelist_array && c.data.whitelist_array.length > 0 && c.data.whitelist_array != '') {
                    var domain = c.data.email.substring(c.data.email.lastIndexOf("@") + 1);
                    c.data.isWhiteListed = c.data.whitelist_array.indexOf(domain) > -1;
                } else if (c.data.whitelist_array == '')
                    c.data.isWhiteListed = true;
                if (c.data.isWhiteListed) {
                    userForm.email.$setValidity('emailWhitelist', true);
                } else
                    userForm.email.$setValidity('emailWhitelist', false);
            }
        };
			c.checkConfirmPassword = function(userForm){
				if(!userForm.confirm_password.$viewValue) return;
				if(userForm.password.$viewValue == userForm.confirm_password.$viewValue)
					userForm.confirm_password.$setValidity('c.confirm_password',true); 
				else
					userForm.confirm_password.$setValidity('c.confirm_password',false); 
			};
        c.validatePassword = function(userForm) {
            c.data.validatePassword = true;
            c.data.password = userForm.password.$viewValue;
            var checkPwd = new Function("password", 'var myFunc =  ' + c.data.pwdRule + '; return myFunc;')();
            var pwdStrength = checkPwd(c.data.password);
            if (pwdStrength == 0)
                userForm.password.$setValidity('c.password', false);
            else
                userForm.password.$setValidity('c.password', true);
        };
        c.showSubmit = function() {
            if (c.data.enableCaptcha == 'true')
                return (c.userid == '' || c.email == '' || c.first_name == '' || c.last_name == '' || c.password == '' || c.confirm_password == '' || c.policy == false || c.captchaVerified == false || c.grc == '');
            else
                return (c.userid == '' || c.email == '' || c.first_name == '' || c.last_name == '' || c.password == '' || c.confirm_password == '' || c.policy == false);
        };
		c.action = function() {
			var inputObj = {};
			inputObj.grc = c.grc;
			inputObj.userid = (c.userid == null) ? '' : c.userid;
			inputObj.first_name = (c.first_name == null) ? '' : c.first_name;
			inputObj.last_name = (c.last_name == null) ? '' : c.last_name;
			inputObj.middle_name = (c.middle_name == null) ? '' : c.middle_name;
			inputObj.email = (c.email == null) ? '' : c.email;
			if(!inputObj.userid){
				inputObj.userid = inputObj.email;
			}
			inputObj.phone_number = (c.phone_number == null) ? '' : c.phone_number;
			inputObj.password = (c.password == null) ? '' : c.password;
			inputObj.portal_id = c.data.portal_id;
			inputObj._tc_number = c.data._tc_number;


			var resourceUrl = '/api/now/externaluser/register';
			$http.post(resourceUrl, inputObj)
				.then(function(resp) {
				window.location.href = "/" + c.data.portal_url_suffix + "?id=" + c.data.landing_page + "&register_response=" + resp.data.result.message;
			}, function(error) {
				if(error.data.result && error.data.result.message && error.data.result.message === 'invalidGRC') {
					c.data.captcha_error = true;
				} else {
					c.data.error = true;
				}
			});
		};

		$scope.$on('$locationChangeStart', function (event, next, current) {
			var nextPage=next+'';
			if(nextPage.indexOf(c.data.login_page) > 0)
				$window.sessionStorage.setItem('navToUri','?id='+c.data.landing_page);
		});
        c.login = function() {
            $location.url("/" + c.data.portal_url_suffix + "?id=" + c.data.portal_login);
        };
    }
}

sp_widget.css:
.text-muted {
     font-weight 500px;
  	color: $gray-dark;
}
.field-decoration-indicator{
  padding-right: 2.5px;
}
.field-decoration-indicator-text{
  margin-bottom: 25px;
}
a{
  color : $link-color !important;
}
a:hover{
    color: $link-hover-color !important;
}
 input[type=text]::-ms-clear {
     display: none;
}
 input::-ms-clear {
     display: none;
}
 .panel-body {
     padding: 20px;
}
 .exiting-username {
     padding: 10px;
     margin-bottom: 10px;
}
 #reg-form{
   .text-success {
     color: $field-success-text;
   }
     .reg-header {
         height: 27px;
         font-size: 23px;
         font-weight: 500;
         line-height: 27px;
         margin-bottom: 28px;
    }
     .registration-label {
         font-size: 16px;
         line-height: 19px;
    }
     .inpt-fields {
         position: relative;
         padding: 5px;
         padding-left: 0px;
    }
     .inner-addon .glyphicon {
         position: absolute;
         padding: 10px;
         pointer-events: none;
         padding-right: 15px;
         right: 0px;
    }
     .inpt-fields input {
         padding-right: 30px;
    }
     .glyphicon {
         top: inherit;
    }
     .glyphicon-ok {
         color:$text-success;
    }
     .glyphicon-remove {
         color:$text-danger;
    }
     .has-success .form-control {
         border-color:$text-success;
    }
     .has-error .form-control {
         border-color:$text-danger;
    }
     .form-validation-rules{
         padding:15px;
         padding-bottom:10px;
         background-color: $gray-lighter;
         font-size: 14px;
    }
     .icon {
         display: table-cell;
         vertical-align: middle;
    }
     .rules-outer{
         padding-left:10px;
         padding-bottom:5px;
    }
     .rules-text {
         padding-left:10px;
         padding-right: 10px;
         display: table-cell;
         vertical-align: top;
         font-size: 14px;
         line-height: 19px;
    }
     .form-group{
         padding-bottom:5px;
    }
     .account-existing{
         padding-top:10px;
         text-align: center;
         vertical-align: middle;
    }
     .form-link .icon{
         position:absolute;
    }
     .policy-check{
         font-size:14px;
         padding-top: 3px;
         padding-left: 15px;
    }
     .form-link{
         display:table;
         padding-left:5px;
         margin-bottom:0px;
         font-size: 16px;
         line-height: 24px;
    }
     .link-text{
         padding-left:5px;
    }
     #password-rule .fa{
         font-size:7px;
    }
     .form_link a {
         color: -webkit-link;
         text-decoration: underline 
    }
    .form_link a:focus {
        outline: auto -webkit-focus-ring-color !important 
    }
    input[type="checkbox"]:focus{
       outline:5px solid $input-border-focus !important;
    }
   .terms-and-conditions-text{
     margin-left: 10px;
}
   .terms-conditions-label {
     font-size: 15px;
     display: inline;
   }
 #html_element{
     transform:scale(1.05);
     -webkit-transform:scale(1.05);
     transform-origin:0 5;
     -webkit-transform-origin:0 0;
}
 @media (max-width: 375px) {
     #html_element{
         transform:scale(0.8);
         -webkit-transform:scale(0.8);
         transform-origin:0 0;
         -webkit-transform-origin:0 0;
    }
}
 .g-recaptcha{
     padding-bottom: 10px;
}
 #captcha_form_group{
     margin-bottom:0px;
   #captchaVerified{
     display:none;
   }
}

sp_widget.script:
(function () {
  data.portal = $sp.getPortalRecord();
  data.portal_url_suffix = data.portal.getValue("url_suffix") + "";
  data.landing_page = $sp.getPortalRecord().homepage.id + "";
  if (gs.isLoggedIn()) {
    data.isloggedIn = true;
    return;
  }
  data.has_extrnl_plugin = GlidePluginManager.isActive(
    "com.sn_external_user_register"
  );
  if (data.has_extrnl_plugin) {
    data.portal_id = data.portal.getUniqueValue();
    data.portal_name = data.portal.getValue("title") + "";
    data.portal_login = data.portal.login_page.id + "" || "csm_login";
    data.login_page = options.login_page || "";
    data.communityUser = false;
    data.emailError = true;
    data.captcha_prop = options.captcha_prop_name;
    data.captch_url =
      "https://www.google.com/recaptcha/api.js?onload=onloadCallback&render=explicit&hl=" +
      gs.getSession().getLanguage();
    data.enableCaptcha = gs.getProperty(data.captcha_prop, "true");
    data.captchaSiteKey = gs.getProperty("google.captcha.site_key");
    data.cred_sysid =
      options.cred_sysid ||
      gs.getProperty(
        "sn_customerservice.csm_portal.pwd_cred_store",
        "6e51033fbf020100710071a7bf0739e0"
      );
    var session = gs.getSession();
    var external_utils = new sn_ext_usr_reg.ExternalUserManagmentUtils(
      data.portal_id
    );
    var whitelist = gs.getProperty("sn_ext_usr_reg.allowed_email_domains");
    data.whitelist_array = "";
    if (whitelist)
      data.whitelist_array = whitelist.replace(/\s/g, "").split(",");
    data.sysuser_email_exists = false;
    data.temprec_email_exists = false;
    var privacyPolicyText = gs.getMessage("Privacy Policy");
    var customerTermsText = gs.getMessage(
      "Customer Service Terms and Conditions"
    );
    var privacyPolicy =
      "<a href=/sn_customerservice_registration_privacy_policy_doc.do target=_blank>&nbsp;" +
      privacyPolicyText +
      "</a>";
    var customerTerms =
      "<a href=/sn_customerservice_registration_terms_doc.do target=_blank>&nbsp;" +
      customerTermsText +
      "</a>";
    var termsConditions = gs.getMessage("I agree to the {0} and the {1}", [
      privacyPolicy,
      customerTerms,
    ]);
    var termsConditionsText = gs.getMessage("I agree to the {0} and the {1}", [
      privacyPolicyText,
      customerTermsText,
    ]);
    var here = gs.getMessage("here");
    data.termsConditions = termsConditions;
    data.termsConditionsText = termsConditionsText;
    data.pwdRule = "";
    data.pwdHints_array = [];
    data.labelMap = {
      email: gs.getMessage("Email Address"),
      first_name: gs.getMessage("First Name"),
      last_name: gs.getMessage("Last Name"),
      phone_number: gs.getMessage("Phone Number"),
      password: gs.getMessage("Password"),
      confirm_password: gs.getMessage("Confirm Password"),
    };
    data.fieldSuccessMsgs = {
      email: gs.getMessage("{0} valid", "Email address"),
      first_name: gs.getMessage("{0} valid", "First name"),
      last_name: gs.getMessage("{0} valid", "Last name"),
      phone_number: gs.getMessage("{0} valid", "Phone number"),
      password: gs.getMessage("{0} valid", "Password"),
      confirm_password: gs.getMessage("Passwords match"),
    };
    data.fieldErrorMsgs = {
      email_invalid_format: gs.getMessage(
        "Enter a valid email address in the format name@example.com"
      ),
      email_invalid_size: gs.getMessage(
        "Email address should be less than 100 characters"
      ),
      first_name: gs.getMessage("{0} invalid", "First name"),
      last_name: gs.getMessage("{0} invalid", "Last name"),
      phone_number: gs.getMessage("{0} invalid", "Phone number"),
      password: gs.getMessage(
        "Enter a valid password. Acceptable passwords are at least 8 characters long and contain at least one uppercase letter (from A to Z), one lowercase letter (from a to z), and one number (from 0 to 9)"
      ),
      confirm_password: gs.getMessage(
        "The values in the Password and Confirm Password fields must match"
      ),
    };
    data.requiredLabel = gs.getMessage("Required");
    data.requiredFilledLabel = gs.getMessage("Required Filled");
    var liStartTagString =
      '<li class="rules-outer"><div class="icon"><i class="fa fa-circle"></i></div> <div class="rules-text">';
    var liEndTagString = "</li>";
    if (options.cred_sysid) {
      var credGr = new GlideRecord("pwd_cred_store");
      if (credGr.get(data.cred_sysid)) {
        data.pwdHints = credGr.getDisplayValue("pwd_rule_hint");
        data.pwdRule = credGr.getValue("strength_rule");
        data.pwdHints = data.pwdHints.replaceAll("-", "");
        data.pwdHints = data.pwdHints.replaceAll("<p>", liStartTagString);
        data.pwdHints = data.pwdHints.replaceAll("</p>", "</li></li>");
      }
    } else {
      data.procId = gs.getProperty(
        "global.glide.service_portal.default_password_process",
        "c6b0c20667100200a5a0f3b457415ad5"
      );
      var passwordUtil = new global.PasswordResetScopedUtil();

      data.pwdRule = passwordUtil.getStrengthRule(data.procId);
      var pwdRuleHints = passwordUtil.getPasswordRules(data.procId);

      if (pwdRuleHints.rulesWithRegex || pwdRuleHints.rulesWithoutRegex) {
        var pwdRules = [
          ...pwdRuleHints.rulesWithRegex,
          ...pwdRuleHints.rulesWithoutRegex,
        ];
        var hints = liStartTagString + pwdRules[0].hint + liEndTagString;
        for (var j = 1; j < pwdRules.length; j++) {
          hints = hints.concat(
            liStartTagString + pwdRules[j].hint + liEndTagString
          );
        }
        data.pwdHints = hints;
      } else {
        data.pwdHints = pwdRuleHints
          .replaceAll("-", "")
          .replaceAll("<p>", liStartTagString)
          .replaceAll("</p>", "</li></li>");
      }
    }
    if (
      input &&
      input.email &&
      input.resend_link &&
      input.action != "register"
    ) {
      var resendResponse = external_utils.resendLink(input.email);
      data.message_txt = resendResponse.message_txt;
      data.message = resendResponse.message || "";
      data.status = resendResponse.status || "";
      gs.getSession().putClientData("reg_resp_message", data.message_txt);
      gs.getSession().putClientData("reg_resp_status", data.status);
      gs.getSession().putClientData("reg_email", input.email);
    }
  }
})();
